// What only the platform gives module code, checked where it runs (the
// Lab's Platform screen, which the device runs open on the simulator and
// the emulator): frames reaching a channel through an executor, uncopied;
// a deep link the app opens to itself; a push token, or why there is none
// (iOS); back presses, key presses and a configuration change (Android);
// a component's React Native view props, read from its native view. Each
// probe that doesn't apply to the platform says "none".
import { Channel, delay, NativeBuffer } from "lucent:core";
import { PLATFORM } from "lucent:platform";
import { executor, main, on } from "lucent:thread";
import { onAppEvent } from "lucent:ios";
import { OperationQueue } from "lucent:ios/Foundation";
import { UIApplication, UIWindowScene, type UIView } from "lucent:ios/UIKit";
import { adoptHardwareBuffer, available, currentActivity, onActivityEvent } from "lucent:android";
import { ComponentActivity } from "lucent:android/androidx.activity";
import { ActivityInfo } from "lucent:android/android.content.pm";
import { Color, PixelFormat } from "lucent:android/android.graphics";
import { ImageReader } from "lucent:android/android.media";
import { Handler, Looper } from "lucent:android/android.os";
import { KeyEvent, ViewGroup, type View } from "lucent:android/android.view";

/** How many frames a probe makes, and their side in pixels. */
const FRAMES = 4;
const SIDE = 64;

/** What a deep link to the app holds, so that the probe knows its own. */
const PROBE = "lucent-probe";

/** Waits until `ready()`, at most `ms`. */
async function until(ready: () => boolean, ms: number): Promise<void> {
  for (let waited = 0; !ready() && waited < ms; waited += 50) await delay(50);
}

/** Receives what `out` holds: how many frames, and the first byte of the last. */
async function drain(out: Channel<NativeBuffer>): Promise<{ count: number; first: number }> {
  const sent = out.stats().sent;
  let count = 0;
  let first = -1;
  for (let i = 0; i < sent; i++) {
    const frame = await out.receive();
    if (!frame) break;

    count += 1;
    first = frame.withRead((bytes) => bytes[0] ?? -1);
    frame.close();
  }
  return { count, first };
}

/**
 * Frames through an executor into a channel, as a camera's would come:
 * an ImageReader's on Android, each adopted where it arrives
 * (adoptHardwareBuffer) and moved through the channel, so nothing copies
 * them. The simulator has no camera, and frames the platform makes from a
 * C API (CVPixelBufferCreate) aren't bound yet: there an OperationQueue on
 * the executor's queue makes buffers.
 */
export async function frames(): Promise<string> {
  return PLATFORM === "ios" ? iosFrames() : androidFrames();
}

async function iosFrames(): Promise<string> {
  const queue = executor("platform.frames");
  const out = new Channel<NativeBuffer>("lossless", 16);
  const operations = new OperationQueue();
  operations.underlyingQueue = queue;

  const before = NativeBuffer.stats();
  for (let i = 0; i < FRAMES; i++)
    operations.addOperation(
      on(queue, () => {
        const frame = NativeBuffer.allocate(SIDE * SIDE * 4);
        frame.withWrite((bytes) => bytes.fill(255));
        out.send(frame);
      }),
    );

  await until(() => out.stats().sent >= FRAMES, 5000);
  const { count } = await drain(out);
  const after = NativeBuffer.stats();

  return `${count} frames, ${after.copies - before.copies} copies`;
}

async function androidFrames(): Promise<string> {
  if (!available("android", 28)) return "needs Android 9, for Image.getHardwareBuffer";

  const reader = ImageReader.newInstance(SIDE, SIDE, PixelFormat.RGBA_8888, 3);
  const surface = reader?.getSurface();
  const looper = Looper.getMainLooper();
  if (!reader || !surface || !looper) return "no ImageReader";

  const queue = executor("platform.frames");
  const out = new Channel<NativeBuffer>("lossless", 16);
  // The listener is called on the main thread's Handler, and runs in a turn of the executor.
  reader.setOnImageAvailableListener(
    on(queue, (from: ImageReader | null) => {
      const image = from?.acquireNextImage();
      if (!image) return;

      const pixels = image.getHardwareBuffer();
      if (pixels) {
        out.send(adoptHardwareBuffer(pixels));
        pixels.close();
      }
      image.close();
    }),
    new Handler(looper),
  );

  const before = NativeBuffer.stats();
  let count = 0;
  let first = -1;
  for (let i = 0; i < FRAMES; i++) {
    const canvas = surface.lockCanvas(null);
    if (!canvas) break;
    canvas.drawColor(Color.RED);
    surface.unlockCanvasAndPost(canvas);

    // One frame at a time: an adopted frame's buffer stays locked for reading until it's
    // closed, and the reader may hand the next frame the same buffer.
    await until(() => out.stats().sent > i, 3000);
    if (out.stats().sent <= i) break;
    const frame = await out.receive();
    if (!frame) break;

    count += 1;
    first = frame.withRead((bytes) => bytes[0] ?? -1);
    frame.close();
  }
  const after = NativeBuffer.stats();
  reader.close();
  surface.release();

  return `${count} frames, ${after.adopted - before.adopted} adopted, ${after.copies - before.copies} copies, red ${first}`;
}

let watching = false;
let lastLink = "";

/** Listens for the deep links the app opens to itself, from now on. */
export async function watchLinks(): Promise<void> {
  if (watching) return;
  watching = true;

  if (PLATFORM === "ios") {
    onAppEvent("openURL", (url) => {
      if (!url.includes(PROBE)) return false;

      lastLink = url;
      return true;
    });
  } else {
    onActivityEvent("newIntent", (_activity, intent) => {
      const url = intent?.getDataString() ?? "";
      if (url.includes(PROBE)) lastLink = url;
    });
  }
}

/** The last deep link of the probe's the app delegate or the Activity received: "" for none. */
export async function lastLinkHeard(): Promise<string> {
  return lastLink;
}

let registered = false;
let pushAnswer = "";

/**
 * Registers for push notifications: iOS answers with a token, or with why
 * there is none (a build without the aps-environment entitlement, as the
 * simulator's unsigned one is).
 */
export async function registerForPush(): Promise<void> {
  if (PLATFORM !== "ios") return;
  if (registered) return;
  registered = true;

  onAppEvent("pushToken", (token) => {
    pushAnswer = `token of ${token.length} bytes`;
  });
  onAppEvent("pushTokenFailed", (error) => {
    pushAnswer = `failed: ${error.message}`;
  });
  await main(() => UIApplication.shared.registerForRemoteNotifications());
}

/** What registering for push notifications answered: "" until it does. */
export async function pushAnswered(): Promise<string> {
  return PLATFORM === "ios" ? pushAnswer : "none";
}

/**
 * Presses back through the Activity's OnBackPressedDispatcher, as the
 * system does: React Native's JavaScript hears it first, and when it
 * doesn't consume it, the module's handler does.
 */
export async function pressBack(): Promise<string> {
  if (PLATFORM !== "android") return "none";

  let heard = 0;
  const stop = onActivityEvent("backPressed", () => {
    heard += 1;
    return true;
  });
  await main(() => {
    const activity = currentActivity();
    if (activity instanceof ComponentActivity)
      activity.getOnBackPressedDispatcher()?.onBackPressed();
  });

  await until(() => heard > 0, 5000);
  stop();

  return heard === 1 ? "consumed" : `${heard} presses`;
}

/**
 * Presses a key nothing in the app handles (F12) through the Activity's
 * window, as the system delivers keys: the module hears it go down and
 * come up, after the app's views and Activity let it through.
 */
export async function pressKey(): Promise<string> {
  if (PLATFORM !== "android") return "none";

  const heard: string[] = [];
  const stopDown = onActivityEvent("keyDown", (_activity, key) => {
    heard.push(`down ${key.getKeyCode()}`);
    return true;
  });
  const stopUp = onActivityEvent("keyUp", (_activity, key) => {
    heard.push(`up ${key.getKeyCode()}`);
    return true;
  });

  await main(() => {
    const window = currentActivity()?.getWindow();
    const decor = window?.getDecorView();
    decor?.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_F12));
    decor?.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP, KeyEvent.KEYCODE_F12));
  });
  stopDown();
  stopUp();

  return heard.join(", ") || "nothing heard";
}

/**
 * Turns the Activity to landscape and back: its configuration changes,
 * which module code hears. When it hears none, it says whether the
 * Activity turned, and whether Android made it again instead (its
 * manifest's configChanges lacking orientation).
 */
export async function rotate(): Promise<string> {
  if (PLATFORM !== "android") return "none";

  let changes = 0;
  const stop = onActivityEvent("configurationChanged", () => {
    changes += 1;
  });

  const before = await main(() => currentActivity()?.hashCode() ?? 0);
  await main(() =>
    currentActivity()?.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE),
  );
  await until(() => changes > 0, 5000);
  const turned = changes;
  if (!turned) {
    const after = await main(() => currentActivity()?.hashCode() ?? 0);
    const orientation = await main(
      () => currentActivity()?.getResources()?.getConfiguration()?.orientation ?? 0,
    );
    if (after !== before) {
      stop();
      return "no change heard: Android made the Activity again";
    }
    // Whether the Activity's own listeners hear the turn back, which Lucent's should be among.
    let heard = 0;
    await main(() => {
      const activity = currentActivity();
      if (activity instanceof ComponentActivity)
        activity.addOnConfigurationChangedListener(() => {
          heard += 1;
        });
    });
    await main(() =>
      currentActivity()?.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED),
    );
    await until(() => heard > 0, 5000);
    stop();
    return `no change heard, orientation ${orientation}; a listener added now ${heard ? `heard the turn back${changes ? ", and so did Lucent's" : ""}` : "heard nothing"}`;
  }

  await main(() =>
    currentActivity()?.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED),
  );
  await until(() => changes > turned, 5000);
  stop();

  return "changed";
}

/**
 * What the platform's accessibility API reads from the native view React
 * Native gave `testID` (Android's tag, iOS's accessibilityIdentifier),
 * which a Lucent component's view gets as any React Native view does: its
 * label, on iOS a member UIKit adds to every NSObject. "no view" when no
 * view has the testID, "no label" when it has no label.
 */
export async function labelOf(testID: string): Promise<string> {
  if (PLATFORM === "android")
    return main(() => {
      const root = currentActivity()?.getWindow()?.getDecorView();
      const views: View[] = root ? [root] : [];
      while (views.length) {
        const view = views.pop()!;
        if (view.getTag()?.toString() === testID)
          return view.createAccessibilityNodeInfo()?.getContentDescription() ?? "no label";
        if (view instanceof ViewGroup)
          for (let i = 0; i < view.getChildCount(); i++) {
            const child = view.getChildAt(i);
            if (child) views.push(child);
          }
      }
      return "no view";
    });

  return main(() => {
    const views: UIView[] = [];
    for (const scene of UIApplication.shared.connectedScenes)
      if (scene instanceof UIWindowScene) for (const window of scene.windows) views.push(window);
    while (views.length) {
      const view = views.pop()!;
      if (view.accessibilityIdentifier === testID) return view.accessibilityLabel ?? "no label";
      for (const subview of view.subviews) views.push(subview);
    }
    return "no view";
  });
}
